public static CredentialMaterial headers(Map<String, SensitiveValue> values) {
    Objects.requireNonNull(values, "values");
    var validated = new LinkedHashMap<String, SensitiveValue>();
    values.forEach((name, value) -> {
        SensitiveHeader header = new SensitiveHeader(name, value);
        validated.put(header.name(), header.value());
    });
    return new CredentialMaterial(Kind.HEADERS, null, validated);
}

